modules.source:
Kit:=import{"kit/shapes.forb"}
using{Kit.Geometry}
Unit:i64=2
Local:=module{
  Scale<public>(X:i64)<computes>:i64=X*Unit
  Hidden<internal>:i64=7
  Deep<public>:=module{
    Offsets:Kit.Row=array{1,2,3}
    Doubled<public>()<computes>:[]i64=For(X:Offsets,Scale(X)+Hidden)
  }
}
P:Kit.Geometry.point=Kit.Geometry.point{x:=3,y:=4}
Area<public>:i64=Flat.Area(P)
Doubled<public>:[]i64=Local.Deep.Doubled()
Tone<public>:Kit.Geometry.Flat.kind=Flat.kind.square
Grid:Kit.Row=array{5,6}
Total<public>:i64=Kit.Total(Grid)
Short<public>:i64=Kit.Total(array{1})
C:counter=counter{}
Read(X:counter)<transacts>:i64=X.Count
Bumps<public>:i64=C.Bump()+C.Bump()
Seen<public>:i64=Read(C)
Peeked<public>:i64=Kit.Geometry.Peek

Row<public>:=[]i64
Seed<internal>:i64=10
Total<public>(R:Row)<computes>:i64=Attempt(R[0]+R[1],0)
Geometry<public>:=module{
  point<public>:=struct{x:i64=0,y:i64=0}
  Flat<public>:=module{
    kind<public>:=enum<closed>{round,square}
    Area<public>(P:point)<computes>:i64=P.x*P.y+Seed
  }
  counter<public>:=class{
    var<private> Count<public>:i64=0
    Bump<public>()<transacts>:i64=Block{set Self.Count=Self.Count+1;Self.Count}
  }
  Private:=module{
    Secret<public>:i64=99
  }
  Peek<public>:i64=Private.Secret
}
